def main() -> int:
    missing = 0
    for rel, q in QUOTES:
        lines = (ROOT / rel).read_text(encoding="utf-8").splitlines()
        hits = [i + 1 for i, ln in enumerate(lines) if q in ln]
        if hits:
            print(f"FOUND  {rel}:{hits[0]}  {q[:90]}")
        else:
            missing += 1
            print(f"MISSING {rel}  {q[:90]}")
    print(f"checked={len(QUOTES)} missing={missing}")
    return 1 if missing else 0


if __name__ == "__main__":
    sys.exit(main())
